    const rim = []; for (let i = 0; i <= 60; i++) { const a = TAU * i / 60; rim.push(v(Math.cos(a), Math.sin(a), 1)); }
    strokePoly(rim, C.dim, q * 0.7, 1.5, false);
    for (let i = 0; i < 12; i++) { const a = TAU * i / 12, p = v(Math.cos(a), Math.sin(a), 1); line(O[0], O[1], p[0], p[1], C.dim, q * 0.25, 1); }
    lbl('null cone', v(1, 0, 1)[0] + 20, v(1, 0, 1)[1], C.dim, q, 15, 'left');
